import {routeTo,slideMove} from './venues.js';
import {Mode} from './mode-base.js';
import {THREE,box,sphere,cylinder,ring,ball,moveActor,distance,palette} from './world.js';
export function traditional(ctx){const constructors={pilolo:Pilolo,stay:Stay,alikoto:Alikoto,tumatu:Tumatu,kpitinge:PegToss,alasa:Alasa,numbers:Numbers,chempe:Chempe,pempenaa:Pempenaa,mbobagor:Mbobagor};return constructors[ctx.game.id]?new constructors[ctx.game.id](ctx):null;}
class Pilolo extends Mode{
 constructor(ctx){super(ctx);this.you=this.player(-6,14);this.world.follow?.(this.you);this.solids=this.venue.solids;this.home={x:-6,z:14};this.seekers=[this.player(-7.2,14,0x397e95),this.player(-4.8,14,0xc09c4d)];this.round=0;this.scores=[0,0,0];this.carried=null;this.places=[];this.circle(-6,14,1.4);this.text('HOME',-6,.1,14,'#ead6a3',.35);
 const locations=[[-14,-13],[-5,-13],[5,-13],[14,-13],[-14,-4],[-5,-4],[6,-4],[14,-3],[-14,5],[-4,4],[6,6],[14,13],[0,14],[8,14]];
 locations.forEach(([x,z],i)=>{const g=new THREE.Group();g.position.set(x,0,z);this.root.add(g);const lid=i%3===0?box(.65,.045,.5,0x8a7960,0,.47,0,g):cylinder(.38,.4,.05,0x9b8764,0,.52,0,g,16);if(i%3===0)box(.65,.45,.5,0x716148,0,.225,0,g);else cylinder(.36,.3,.48,i%2?0x737c67:0x927a57,0,.24,0,g,16);const stick=cylinder(.025,.035,.4,0xc5b382,0,.24,0,g,8);stick.visible=false;this.places.push({x,z,g,lid,stick,lidY:lid.position.y,has:false,opened:false,name:i%3===0?'doorstep box':i%2?'water pot':'basket'});});
 this.setActions([{id:'search',label:'Search / collect',key:'Space'},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);this.newRound();
 }
 newRound(){this.phase='ready';this.time=0;this.carried=null;this.you.position.set(-6,0,14);this.you.userData.run=0;this.input.target=null;this.route=[];for(const q of this.places){q.has=false;q.opened=false;q.lid.position.y=q.lidY;q.lid.rotation.z=0;q.stick.visible=false;q.stick.position.set(0,.24,0);}const shuffled=this.places.map((_,i)=>i).sort(()=>Math.random()-.5);shuffled.slice(0,3).forEach(i=>this.places[i].has=true);this.seekers.forEach((p,i)=>{p.position.set(i?-7.2:-4.8,0,14);Object.assign(p.userData,{found:false,choice:shuffled[3+i],searchDelay:0,route:[],planning:0});});this.note('The leader has hidden three sticks around the neighbourhood. Wait for PILOLO!');}
 action(){if(this.phase!=='search')return;if(this.carried){if(distance(this.you,this.home)<1.5)this.endRound(0);return;}const q=this.places.find(p=>distance(this.you,p)<1.5&&!p.opened);if(!q){this.note('Search a covered basket, pot or box near a doorway. Move close first.');return;}this.open(q);this.you.userData.pose='reach';this.delay=.4;if(q.has){this.carried=q.stick;q.has=false;q.stick.visible=true;this.note('Found one! Race HOME through the alleys.');this.ui.sound('point');}else this.note('Empty '+q.name+'. Search another courtyard.');}
 open(q){q.opened=true;q.lid.rotation.z=.65;q.lid.position.y=q.lidY+.15;this.ui.sound('stone');}
 endRound(winner){if(this.phase==='result')return;if(winner!==null)this.scores[winner]++;this.round++;this.phase='result';this.time=0;this.input.target=null;this.note(winner===0?'First home! You win this round.':winner===null?'No one returned. The leader hides again.':'A rival got home first. New hiding places next round.');this.ui.sound(winner===0?'goal':'call');}
 hit({point}){this.input.target=point;this.route=routeTo(this.you.position,point,this.solids);}
 walk(p,target,speed,dt){const v=new THREE.Vector3(target.x-p.position.x,0,target.z-p.position.z);if(v.length()<.2)return 0;v.normalize().multiplyScalar(speed);slideMove(p.position,v,dt,this.solids);p.rotation.y=Math.atan2(v.x,v.z);return 1;}
 update(dt){this.status(`YOU ${this.scores[0]} · RIVALS ${this.scores[1]+this.scores[2]}`,`ROUND ${Math.min(3,this.round+1)} / 3`);if(this.phase==='ready'){if(this.time>2.2){this.phase='search';this.time=0;this.note('PILOLO! Search the neighbourhood, find one stick, race home.');this.ui.sound('call');}return;}if(this.phase==='result'){if(this.time>2){if(this.round>=3){this.score=this.scores[0];return this.finish(this.scores[0]>=2?'QUICKEST IN THE NEIGHBOURHOOD':'THE SEARCH IS OVER',`${this.scores[0]} of 3 races won.`,this.scores[0]>=2);}this.newRound();}return;}
 const raw=this.world.movementVector?.(this.input.vector())||this.input.vector(),v=new THREE.Vector3(raw.x,0,raw.z),speed=this.input.sprint?6.6:4.6;if(v.length()>.1){this.route=[];v.multiplyScalar(speed);slideMove(this.you.position,v,dt,this.solids);this.you.rotation.y=Math.atan2(v.x,v.z);this.you.userData.run=1;}else if(this.route?.length){this.you.userData.run=this.walk(this.you,this.route[0],speed,dt);if(distance(this.you,this.route[0])<.3)this.route.shift();}else this.you.userData.run=0;
 if(this.delay>0){this.delay-=dt;if(this.delay<=0)this.you.userData.pose='idle';}if(this.carried){this.carried.position.set(this.you.position.x-this.carried.parent.position.x,.95,this.you.position.z-this.carried.parent.position.z);if(distance(this.you,this.home)<1.3)this.endRound(0);}
 this.seekers.forEach((p,i)=>{if(this.phase!=='search')return;const u=p.userData;let q=u.found?this.home:this.places[u.choice];if(!u.found&&q.opened){const options=this.places.map((q,j)=>!q.opened?j:-1).filter(j=>j>=0);u.choice=options[Math.floor(Math.random()*options.length)]??u.choice;q=this.places[u.choice];u.route=[];}u.planning-=dt;if(!u.route.length||u.planning<=0){u.route=routeTo(p.position,new THREE.Vector3(q.x,0,q.z),this.solids);u.planning=3;}if(u.route.length){u.run=this.walk(p,u.route[0],u.found?4.1:3.5,dt);if(distance(p,u.route[0])<.3)u.route.shift();}if(distance(p,q)<1.15){if(u.found){this.endRound(i+1);return;}u.searchDelay+=dt;u.pose='reach';u.run=0;if(u.searchDelay>.9){this.open(q);if(q.has){u.found=true;q.has=false;q.stick.visible=false;u.route=[];}u.searchDelay=0;u.pose='idle';}}});if(this.time>150)this.endRound(null);
 }
}
class Stay extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([4,3.6,10,0,1,0]);this.you=this.player(0,4);this.you.rotation.y=Math.PI;this.thrower=this.player(0,-5,0x416e82);this.b=ball(this.root,.12);this.b.position.set(0,1.2,-5);this.phase='moving';this.callAt=2+Math.random()*2;this.round=0;this.frozen=false;this.returned=false;this.v=new THREE.Vector3();this.setActions([{id:'freeze',label:'Stay!',key:'Space'},{id:'foot',label:'Kick return',key:'E'},{id:'head',label:'Header',key:'Q'}]);this.note('Move until STAY. Plant your feet, then time a kick or header.');}
 action(id){if(id==='freeze'&&this.phase==='call'){this.frozen=true;this.input.target=null;this.note('Feet planted. Watch the height of the ball.');return;}if(this.phase!=='throw'||this.returned)return;const d=distance(this.b,this.you),height=this.b.position.y;if(d<1.1&&(id==='foot'&&height<.8||id==='head'&&height>1.3)){this.returned=true;this.you.userData.kick=id==='foot'?.38:0;this.you.userData.pose=id==='head'?'head':'idle';this.v.copy(this.thrower.position).sub(this.b.position).normalize().multiplyScalar(12);this.v.y=2;this.score++;this.ui.sound('kick');this.note('Clean return. Your feet stayed planted.');}else this.note(id==='head'?'Wait for the high ball to reach you.':'Time the kick as the low ball reaches your foot.');}
 next(text){this.round++;this.phase='result';this.time=0;this.note(text);}
 update(dt){this.status(`${this.score} RETURNS`,`${Math.min(5,this.round+1)} / 5`);if(this.phase==='moving'){this.move(this.you,dt,4,6);if(this.time>this.callAt){this.phase='call';this.time=0;this.you.userData.run=0;this.note('STAY! Press Stay and keep your feet planted.');this.ui.sound('call');}}else if(this.phase==='call'&&this.time>1.2){if(!this.frozen)return this.next('You missed the call. Try the next round.');this.phase='throw';this.time=0;this.returned=false;this.high=Math.random()>.5;const duration=.95;this.b.position.set(0,1.2,-5);this.v.set((this.you.position.x-this.b.position.x)/duration,((this.high?1.65:.35)-1.2+4.905*duration*duration)/duration,(this.you.position.z+5)/duration);this.thrower.userData.kick=.38;this.note(this.high?'High ball — time your header.':'Low ball — time your kick.');}else if(this.phase==='throw'){this.b.position.addScaledVector(this.v,dt);this.v.y-=9.81*dt;if(this.b.position.y<.12){this.b.position.y=.12;this.v.y=Math.abs(this.v.y)*.45;}if(this.time>1.7)this.next(this.returned?'Returned! Get ready for another call.':'The ball got past you. Watch its height.');}else if(this.phase==='result'&&this.time>1.5){if(this.round>=5)return this.finish('STAY — ROUND COMPLETE',`${this.score} of 5 balls returned with planted feet.`,this.score>=3);this.phase='moving';this.time=0;this.frozen=false;this.you.userData.pose='idle';this.b.position.set(0,1.2,-5);this.note('Move again. Wait for the next STAY call.');}}
 hit({point}){if(this.phase==='moving')this.input.target=point;}
}
class Alikoto extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([1.8,2.2,3.8,0,.2,0]);this.you=this.player(-1.2,.7);this.you.rotation.y=1.9;this.you.userData.pose='knees';this.prop=new THREE.Group();this.root.add(this.prop);cylinder(.19,.19,.065,0xa6a59c,0,0,0,this.prop,32);cylinder(.04,.045,.64,0x284f66,0,.34,0,this.prop,16);this.prop.position.set(0,.035,0);this.circle(0,0,.65);this.phase='ready';this.attempt=0;this.power=.45;this.charge=null;this.v=new THREE.Vector3();this.setActions([{id:'strike',label:'Palm strike',key:'Space',charge:true},{id:'power',label:'Set strength',key:'E'}]);this.note('An improvised pen-cap spinner. Hold Palm strike, then release to flip it onto its base.');}
 hold(id){if(id==='strike'&&this.phase==='ready')this.charge=this.age;}
 action(id){if(this.phase!=='ready')return;if(id==='power'){this.power=this.power>=.8?.3:this.power+.1;return;}if(this.charge!==null)this.power=THREE.MathUtils.clamp(.25+(this.age-this.charge)*.55,.25,.9);this.charge=null;this.phase='flight';this.time=0;this.prop.position.set(0,.1,0);this.prop.rotation.set(0,0,0);this.v.set(.06,1.5+this.power*3.8,.05);this.angular=5+this.power*10;this.you.userData.pose='reach';this.ui.sound('clap');}
 update(dt){const power=this.charge===null?this.power:THREE.MathUtils.clamp(.25+(this.age-this.charge)*.55,.25,.9);this.status(`${this.score} CLEAN LANDINGS`,`${Math.min(5,this.attempt+1)} / 5 · STRENGTH ${Math.round(power*100)}%`);if(this.phase==='flight'){this.v.y-=9.81*dt;this.prop.position.addScaledVector(this.v,dt);this.prop.rotation.z+=this.angular*dt;this.prop.rotation.y+=dt*3;if(this.prop.position.y<=.035&&this.v.y<0){const up=Math.cos(this.prop.rotation.z),ok=up>.92&&Math.hypot(this.prop.position.x,this.prop.position.z)<.65;this.prop.position.y=.035;this.prop.rotation.z=ok?0:Math.PI/2;if(ok)this.score++;this.attempt++;this.phase='result';this.time=0;this.note(ok?'Landed on its metal base.':'On its side. Adjust the force of the next strike.');this.ui.sound(ok?'point':'stone');}}else if(this.phase==='result'&&this.time>1.5){if(this.attempt>=5)return this.finish('ALIKOTO — ROUND COMPLETE',`${this.score} upright landings in five strikes.`,this.score>=3);this.phase='ready';this.you.userData.pose='knees';this.prop.position.set(0,.035,0);this.prop.rotation.set(0,0,0);}}
}
class PegToss extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([3,3.8,9,0,.5,-1]);this.you=this.player(-1,3);this.you.rotation.y=Math.PI;this.prop=new THREE.Group();this.root.add(this.prop);cylinder(.04,.065,.8,0xc3b387,0,0,0,this.prop,12);cylinder(.11,.07,.2,0x797a70,0,-.38,0,this.prop,12);this.prop.position.set(0,1.1,3);const mound=sphere(1.3,0xba8c62,0,.07,-3,this.root,32);mound.scale.y=.22;this.phase='ready';this.attempt=0;this.aim=0;this.v=new THREE.Vector3();this.setActions([{id:'throw',label:'Toss peg',key:'Space'}]);this.note('Aim at the mound. Release near vertical; the actual landing decides the point.');}
 action(){if(this.phase!=='ready')return;this.phase='flight';this.time=0;this.v.set(Math.sin(this.aim)*6,4.3,-6);this.angular=6.1;this.you.userData.pose='point';this.ui.sound('swing');}
 hit({point}){if(this.phase==='ready')this.aim=THREE.MathUtils.clamp(Math.atan2(point.x,3-point.z),-.5,.5);}
 update(dt,t){this.status(`${this.score} PLANTED`,`${Math.min(5,this.attempt+1)} / 5`);if(this.phase==='ready'){this.aim=THREE.MathUtils.clamp(this.aim+this.input.vector().x*dt*.5,-.5,.5);this.prop.rotation.z=Math.sin(t*3)*.55;this.prop.rotation.y=this.aim;}else if(this.phase==='flight'){this.v.y-=9.81*dt;this.prop.position.addScaledVector(this.v,dt);this.prop.rotation.z+=this.angular*dt;if(this.prop.position.y<=.45){const inMound=distance(this.prop,{x:0,z:-3})<1.2,up=Math.cos(this.prop.rotation.z)>.91,ok=inMound&&up;if(ok)this.score++;this.prop.position.y=ok?.5:.12;this.prop.rotation.z=ok?0:Math.PI/2;this.attempt++;this.phase='result';this.time=0;this.note(ok?'The weighted point planted in the mound.':!inMound?'Outside the mound. Adjust your aim.':'The peg fell sideways. Adjust the release timing.');this.ui.sound(ok?'point':'stone');}}else if(this.time>1.5){if(this.attempt>=5)return this.finish('KPITINGE — ROUND COMPLETE',`${this.score} of five pegs planted upright.`,this.score>=3);this.phase='ready';this.prop.position.set(0,1.1,3);this.you.userData.pose='idle';}}
}
class Tumatu extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([2.4,7,10,0,.1,1]);this.you=this.player(0,6.5);this.you.rotation.y=Math.PI;this.positions=[[-.45,5],[.45,4],[-.45,3],[.45,2],[-.45,1],[.45,0],[-.45,-1],[.45,-2]];this.route=[0,1,2,4,5,6,7,6,5,4,2,1,0];this.next=0;for(let i=0;i<8;i++){const [x,z]=this.positions[i];for(const [dx,dz,w,d]of [[0,-.45,.9,.018],[0,.45,.9,.018],[-.45,0,.018,.9],[.45,0,.018,.9]])box(w,.01,d,0xddd2b4,x+dx,.018,z+dz,this.root);this.text(String(i+1),x,.05,z,'#ded1b0',.22);}const marker=sphere(.075,0x6b5b45,.45,.06,2,this.root,12);marker.scale.y=.4;this.you.userData.pose='left';this.charge=null;this.air=0;this.velocity=new THREE.Vector3();this.aim=null;this.setActions([{id:'hop',label:'Hop',key:'Space',charge:true}]);this.note('Marker in square 4. Hop out and back on one foot. Hold Hop longer for the gap. Tap a square to aim.');}
 hold(){if(this.air<=0)this.charge=this.age;}
 hit({point}){this.aim=point;}
 action(){if(this.air>0||this.done)return;const target=this.aim||new THREE.Vector3(...[this.positions[this.route[this.next]][0],0,this.positions[this.route[this.next]][1]]);const dir=target.clone().sub(this.you.position);dir.y=0;const charge=this.charge===null?.4:THREE.MathUtils.clamp(this.age-this.charge,.35,1.3);this.charge=null;const travel=.8+charge*1.4;this.velocity.copy(dir.normalize().multiplyScalar(travel/.62));this.air=.62;this.you.rotation.y=Math.atan2(dir.x,dir.z);this.ui.sound('jump');}
 update(dt){this.status(`${this.next} / ${this.route.length} HOPS`,this.next<7?'OUTWARD · SKIP 4':'RETURN · SKIP 4');if(this.air>0){const step=Math.min(dt,this.air);this.you.position.addScaledVector(this.velocity,step);this.air-=step;this.you.userData.jump=Math.sin(this.air/.62*Math.PI)*.55;if(this.air<=0){this.you.userData.jump=0;const q=this.positions[this.route[this.next]],inside=Math.abs(this.you.position.x-q[0])<.4&&Math.abs(this.you.position.z-q[1])<.4;if(inside){this.next++;this.score=this.next;this.aim=null;this.ui.sound('point');if(this.next>=this.route.length)return this.finish('OUT AND BACK','You cleared the marked square and kept the hop inside the lines.');this.note('Next: square '+(this.route[this.next]+1)+(this.route[this.next]===4?' — longer hop past the marker.':'.'));}else{this.you.position.set(this.next?this.positions[this.route[this.next-1]][0]:0,0,this.next?this.positions[this.route[this.next-1]][1]:6.5);this.note('Outside the chalk. Retry from your last clean landing.');this.ui.sound('miss');}}}}
}
class Alasa extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([1.5,3.7,5,0,.1,.7]);this.you=this.player(-1.5,1);this.you.rotation.y=Math.PI/2;this.you.userData.pose='knees';this.other=this.player(1.5,1,0x3f7f82);this.other.rotation.y=-Math.PI/2;this.other.userData.pose='knees';cylinder(.14,.12,.025,0x342c22,0,.005,-.5,this.root,24);ring(.17,0x82745b,0,-.5,this.root,.018);this.seed=sphere(.075,0x56301c,0,.06,2.2,this.root,20);this.seed.scale.set(.7,.6,1.6);this.seed.material.roughness=.28;this.turn=0;this.scores=[0,0];this.attempts=[0,0];this.phase='aim';this.power=.55;this.aim=0;this.charge=null;this.v=new THREE.Vector3();this.setActions([{id:'flick',label:'Flick seed',key:'Space',charge:true},{id:'power',label:'Set strength',key:'E'}]);this.note('Five seeds each. Aim at the little hole; hold Flick to set strength. Sunk seeds count.');}
 hold(){if(this.turn===0&&this.phase==='aim')this.charge=this.age;}
 hit({point}){if(this.phase==='aim'&&this.turn===0)this.aim=THREE.MathUtils.clamp(Math.atan2(point.x,2.2-point.z),-.5,.5);}
 action(id){if(this.phase!=='aim'||this.turn!==0)return;if(id==='power'){this.power=this.power>=.9?.3:this.power+.1;return;}if(this.charge!==null)this.power=THREE.MathUtils.clamp(.25+(this.age-this.charge)*.6,.2,1);this.charge=null;this.flick(this.power,this.aim);}
 flick(power,aim){this.phase='rolling';this.time=0;this.seed.position.set(0,.06,2.2);this.v.set(Math.sin(aim)*power*10.4,0,-Math.cos(aim)*power*10.4);(this.turn?this.other:this.you).userData.pose='reach';this.ui.sound('stone');}
 update(dt){this.status(`YOU ${this.scores[0]} — ${this.scores[1]} THEM`,`${this.turn?'THEIR':'YOUR'} SEED ${Math.min(5,this.attempts[this.turn]+1)} / 5`);if(this.phase==='aim'){this.aim=THREE.MathUtils.clamp(this.aim+this.input.vector().x*dt*.3,-.5,.5);if(this.turn===1&&this.time>1.2)this.flick(.48+Math.random()*.12,(Math.random()-.5)*.07);}else if(this.phase==='rolling'){this.seed.position.addScaledVector(this.v,dt);this.v.multiplyScalar(Math.exp(-2.1*dt));this.seed.rotation.x-=this.v.length()*dt/.075;const sunk=distance(this.seed,{x:0,z:-.5})<.13;if(sunk||this.v.length()<.08||this.time>3){if(sunk){this.scores[this.turn]++;this.seed.position.y=-.1;}this.attempts[this.turn]++;this.phase='result';this.time=0;this.note(sunk?'In the hole. One seed won.':'Missed the hole. Next seed.');this.ui.sound(sunk?'point':'stone');}}else if(this.time>1.2){if(this.attempts.every(n=>n>=5)){this.score=this.scores[0];return this.finish(this.scores[0]===this.scores[1]?'HONOURS EVEN':this.scores[0]>this.scores[1]?'YOUR SEEDS WIN':'THEY TAKE THIS ROUND',`${this.scores[0]} – ${this.scores[1]} seeds sunk.`,this.scores[0]>=this.scores[1]);}this.turn=1-this.turn;this.phase='aim';this.time=0;this.seed.position.set(0,.06,2.2);this.you.userData.pose=this.other.userData.pose='knees';}}
}
class Numbers extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,4,9,0,1,0]);this.you=this.player(0,3);this.you.rotation.y=Math.PI;this.group=[];for(let i=0;i<4;i++){const a=i*Math.PI/2,p=this.player(Math.sin(a)*2.8,Math.cos(a)*2.8-1,i%2?0x387b86:0xa88b42);p.rotation.y=a+Math.PI;this.group.push(p);}this.round=0;this.phase='others';this.questions=[[8,7,9],[13,15,12],[21,25,23],[31,33,35],[42,43,49],[51,53,57],[63,65,67],[71,77,81]];this.correct=[1,0,2,0,1,1,2,0];this.setActions([{id:'ready',label:'Ready',key:'Space'}]);this.note('Players name primes in turn. Your response window gets shorter each round.');}
 action(id){if(this.phase!=='you')return;const ok=Number(id)===this.correct[this.round];if(!ok)return this.finish('OUT OF THE CIRCLE',`${this.questions[this.round][this.correct[this.round]]} was prime. You cleared ${this.score} turns.`,false);this.score++;this.round++;this.you.userData.pose='point';this.ui.sound('point');if(this.round>=8)return this.finish('QUICK WITH NUMBERS','Eight prime responses before the clock.');this.phase='others';this.time=0;this.note('Good. Listen while the turn comes around.');}
 update(dt,t){this.status(`${this.score} TURNS CLEARED`,this.phase==='you'?`${Math.max(0,3.5-this.round*.2-this.time).toFixed(1)}s TO ANSWER`:'THE CIRCLE IS ANSWERING');if(this.phase==='others'){this.group.forEach((p,i)=>p.userData.pose=Math.floor(this.time/.45)%4===i?'point':'idle');if(this.time>1.8){this.phase='you';this.time=0;this.you.userData.pose='idle';this.setActions(this.questions[this.round].map((n,i)=>({id:String(i),label:String(n),key:['Space','E','Q'][i]})));this.note('Your turn. Name a prime.');}}else if(this.time>3.5-this.round*.2)this.finish('THE TURN PASSED YOU',`${this.score} turns cleared. Try a quicker response.`,false);}
}
class Chempe extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,2.7,6.2,0,1,0]);this.you=this.player(-1,0);this.other=this.player(1,0,0x397d7f);this.you.rotation.y=Math.PI/2;this.other.rotation.y=-Math.PI/2;this.food=new THREE.Group();this.root.add(this.food);for(let i=0;i<4;i++)sphere(.09,0xc78c38,(i%2)*.17,0,Math.floor(i/2)*.17,this.food,16);this.round=0;this.phase='wait';this.setActions([{id:'no',label:'No Chem pe!',key:'Space'},{id:'claim',label:'Chempε!',key:'E'}]);this.prepare();}
 prepare(){this.holder=this.round%2===0;this.phase='wait';this.time=0;this.revealAt=1+Math.random()*2;this.cpuAt=.65+Math.random()*.6;this.food.visible=false;this.you.userData.pose=this.other.userData.pose='idle';this.note(this.holder?'You hold the food. When it appears, call “No Chem pe!” first.':'You are the claimant. When food appears, call “Chempε!” before the exemption.');}
 action(id){if(this.phase==='wait'){this.resolve(false,'Too early. Wait until the food is revealed.');return;}if(this.phase!=='reveal')return;const ok=this.holder?id==='no':id==='claim';this.resolve(ok,ok?(this.holder?'Exemption remembered. You keep your portion.':'A fair claim. The portions are shared.'):'Wrong call for your role.');}
 resolve(ok,message){if(ok)this.score++;this.round++;this.phase='result';this.time=0;this.food.visible=true;this.food.position.set(0,1,.3);this.food.children.forEach((p,i)=>{p.position.x=(i<2?-.65:.65)+(i%2)*.16;});this.you.userData.pose=this.other.userData.pose='reach';this.note(message);this.ui.sound(ok?'clap':'miss');}
 update(){this.status(`${this.score} QUICK CALLS`,`${Math.min(6,this.round+1)} / 6 · ${this.holder?'FOOD-HOLDER':'CLAIMANT'}`);if(this.phase==='wait'&&this.time>this.revealAt){this.phase='reveal';this.time=0;this.food.visible=true;this.food.children.forEach((p,i)=>p.position.x=(i%2)*.17);this.food.position.set(this.holder?-.65:.65,1,.2);this.note(this.holder?'Food is out — No Chem pe!':'Food is out — claim Chempε!');}else if(this.phase==='reveal'&&this.time>this.cpuAt)this.resolve(false,this.holder?'They claimed a share before your exemption.':'They said “No Chem pe” first.');else if(this.phase==='result'&&this.time>1.4){if(this.round>=6)return this.finish('THE PACT REMEMBERED',`${this.score} of six calls made in time.`,this.score>=4);this.prepare();}}
}
class Pempenaa extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,4.6,7,0,.3,0]);this.people=[];this.legs=Array.from({length:8},()=>true);for(let i=0;i<4;i++){const p=this.player((i-1.5)*1.3,0,i===0?this.settings.color:i%2?0x426d7f:0xaa8d4b);p.userData.pose='sit';this.people.push(p);}this.leader=this.player(0,3,0x687a55);this.leader.rotation.y=Math.PI;this.leader.userData.pose='point';this.pointer=sphere(.045,0xd4c6a5,0,.08,1,this.root);this.index=0;this.ticks=0;this.phrase=9;this.phase='count';this.rank=[];this.setActions([{id:'left',label:'Fold left leg',key:'Space'},{id:'right',label:'Fold right leg',key:'E'}]);this.note('The count passes over each extended leg. Fold only the selected leg when the phrase ends.');}
 activeLegs(){return this.legs.map((v,i)=>v?i:-1).filter(i=>i>=0);}
 fold(i){this.legs[i]=false;const person=Math.floor(i/2),left=this.legs[person*2],right=this.legs[person*2+1];this.people[person].userData.pose=!left&&!right?'knees':!left?'fold-left':'fold-right';if(!left&&!right&&!this.rank.includes(person)){this.rank.push(person);if(person===0){this.score=5-this.rank.length;return this.finish('BOTH LEGS WITHDRAWN',`You finished ${['first','second','third','fourth'][this.rank.length-1]}. Phrase length is an arcade counting choice.`);}}this.phase='count';this.time=0;this.ticks=0;this.phrase=7+Math.floor(Math.random()*7);this.note('A new phrase begins. Follow the remaining legs.');}
 action(id){if(this.phase==='selected'&&this.selected<2){const chosen=id==='left'?0:1;if(chosen===this.selected){this.ui.sound('clap');this.fold(chosen);}else this.note('Only the selected leg folds this time.');}}
 update(){this.status(`${this.legs.slice(0,2).filter(v=>!v).length} / 2 LEGS FOLDED`,this.phase==='selected'?'PHRASE END':'FOLLOW THE COUNT');if(this.phase==='count'&&this.time>.36){this.time=0;const legs=this.activeLegs();if(!legs.length)return;this.index=(this.index+1)%legs.length;this.selected=legs[this.index];this.pointer.position.set((Math.floor(this.selected/2)-1.5)*1.3+(this.selected%2?.16:-.16),.08,.8);this.ui.sound('stone');this.ticks++;if(this.ticks>=this.phrase){this.phase='selected';this.time=0;this.note(this.selected<2?`Your ${this.selected===0?'left':'right'} leg. Fold it.`:'The selected player folds one leg.');}}else if(this.phase==='selected'&&this.selected>=2&&this.time>.7)this.fold(this.selected);}
}
class Mbobagor extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,5.2,7.5,0,.3,0]);this.people=[];this.piles=Array(6).fill(1);this.stones=[];this.beat=0;this.lastBeat=0;this.passed=false;this.period=1.5;for(let i=0;i<6;i++){const a=i*Math.PI/3,p=this.player(Math.sin(a)*2.3,Math.cos(a)*2.3,i===0?this.settings.color:i%2?0x4a7b7a:0xb09451);p.rotation.y=a+Math.PI;p.userData.pose='knees';this.people.push(p);this.stones.push([]);for(let n=0;n<3;n++){const stone=sphere(.09,0x7a7262,Math.sin(a)*1.65,.08+n*.14,Math.cos(a)*1.65,this.root,10);stone.scale.y=.6;stone.visible=n===0;this.stones[i].push(stone);}}this.setActions([{id:'pass',label:'Pass stone',key:'Space'}]);this.note('Everyone has a stone. Pass on each clap; a missed pass leaves a pile in front of you.');}
 action(){const within=this.time<.32||this.time>this.period-.28;if(within&&!this.passed){this.passed=true;this.people[0].userData.pose='reach';this.ui.sound('stone');}else if(!within)this.note('Find the shared beat. Pass with the next clap.');}
 update(dt){this.period=Math.max(.85,1.5-this.score*.035);this.status(`${this.score} PASSES`,`${this.piles[0]} STONES IN YOUR PILE`);if(this.time>=this.period){this.time-=this.period;this.beat++;if(this.beat>1){if(this.passed){this.score++;this.piles[0]=Math.max(1,this.piles[0]-1);}else{this.piles[0]++;this.note('One incoming stone, one missed pass. Your pile grew.');}}this.passed=false;this.ui.sound('clap');this.people.forEach((p,i)=>p.userData.pose=i?'reach':'knees');if(this.piles[0]>=3)return this.finish('THREE STONES COLLECTED',`${this.score} passes in rhythm. Listen for the next beat.`,false);if(this.score>=16)return this.finish('THE CIRCLE STAYS TOGETHER','Sixteen passes with the group.');}
 const progress=THREE.MathUtils.clamp(this.time/.32,0,1);for(let i=0;i<6;i++){const a=i*Math.PI/3,b=(i+1)%6*Math.PI/3;this.stones[i].forEach((s,n)=>{s.visible=n<this.piles[i];if(n===0&&i!==0||n===0&&this.passed){s.position.x=THREE.MathUtils.lerp(Math.sin(a)*1.65,Math.sin(b)*1.65,progress);s.position.z=THREE.MathUtils.lerp(Math.cos(a)*1.65,Math.cos(b)*1.65,progress);s.position.y=.08+Math.sin(progress*Math.PI)*.18;}else s.position.set(Math.sin(a)*1.65,.08+n*.14,Math.cos(a)*1.65);});}if(this.time>.4)this.people.forEach(p=>p.userData.pose='knees');}
}
